// Build Error Payload
// Reads the Error Trigger payload and prepares a safe JSON string for the
// Postgres insert. Escapes single quotes so the SQL string literal is valid.

const event = $input.first().json;

const executionId = event.execution && event.execution.id
  ? String(event.execution.id)
  : `unknown_${Date.now()}`;

const stripeEventId = `error_exec_${executionId}`;

// Escape single quotes for Postgres string literal
const rawJsonEscaped = JSON.stringify(event).replace(/'/g, "''");

return [{
  json: {
    stripe_event_id: stripeEventId,
    overall_status: 'failed',
    raw_event_json: rawJsonEscaped
  }
}];
